using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns information about a message thread. Can be used only if messageProperties.can_get_message_thread == true
    /// </summary>
    public Task<TdLib.TdApi.Objects.MessageThreadInfo> GetMessageThreadAsync(long chatId = default, long messageId = default)
    {

           using var activity =  StartCallActivity("GetMessageThreadAsync", typeof(GetMessageThread).FullName ?? "GetMessageThreadAsync");

           try
           {
             return client.GetMessageThreadAsync(chatId, messageId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
